import{_ as t,o as i,c as e,a2 as r}from"./chunks/framework.BqNd1sPY.js";const p=JSON.parse('{"title":"LLMTrain：零基础大模型训练课","description":"","frontmatter":{},"headers":[],"relativePath":"index.md","filePath":"README.md"}'),d={name:"index.md"};function s(n,a,o,l,c,m){return i(),e("div",null,[...a[0]||(a[0]=[r(`<h1 id="llmtrain-零基础大模型训练课" tabindex="-1">LLMTrain：零基础大模型训练课 <a class="header-anchor" href="#llmtrain-零基础大模型训练课" aria-label="Permalink to &quot;LLMTrain：零基础大模型训练课&quot;">​</a></h1><p>这是一套面向数学和编程基础薄弱学习者的 21 天课程。前 14 天建立正确的知识地图，后 7 天从零训练、评测并记录一个微型语言模型。</p><h2 id="从哪里开始" tabindex="-1">从哪里开始 <a class="header-anchor" href="#从哪里开始" aria-label="Permalink to &quot;从哪里开始&quot;">​</a></h2><ol><li>打开 <a href="./00-从这里开始/">课程入口</a>。</li><li>做一次 <a href="./00-从这里开始/学前自测">学前自测</a>，只用于选择解释深度，不计分。</li><li>每天按 <a href="./00-从这里开始/21天路线图">21 天路线图</a> 学习并完成当日验收。</li><li>遇到公式时再查 <a href="./03-数学急救包/">数学急救包</a>，不必提前学完。</li></ol><h2 id="你最终要能做到" tabindex="-1">你最终要能做到 <a class="header-anchor" href="#你最终要能做到" aria-label="Permalink to &quot;你最终要能做到&quot;">​</a></h2><ul><li>用自己的话解释 <code>数据 -&gt; token -&gt; Transformer -&gt; 概率 -&gt; 文本</code>。</li><li>区分<a href="/LLMTrain/05-速查表/术语速查#term-pretraining" class="wiki-term" data-wiki-title="pretraining" data-wiki-summary="在大规模数据上学习通用模式的基础训练阶段。" data-wiki-misconception="预训练数据越多，模型回答就必然越真实。">预训练</a>、<a href="/LLMTrain/05-速查表/术语速查#term-sft" class="wiki-term" data-wiki-title="SFT" data-wiki-summary="用输入与理想输出示例进行监督训练，使模型更符合目标行为。" data-wiki-misconception="SFT 会自动完成事实核验。">监督微调</a>、偏好对齐、<a href="/LLMTrain/05-速查表/术语速查#term-rag" class="wiki-term" data-wiki-title="RAG" data-wiki-summary="先检索外部资料，再把相关片段放进上下文辅助生成。" data-wiki-misconception="检索到资料就能保证资料和答案都真实。">RAG</a> 和 <a href="/LLMTrain/05-速查表/术语速查#term-agent" class="wiki-term" data-wiki-title="Agent" data-wiki-summary="让模型参与工具选择、读取结果和多步决策循环的应用结构。" data-wiki-misconception="Agent 可以脱离权限、预算和人工确认自主执行。">Agent</a>，知道何时不该训练模型。</li><li>看懂<a href="/LLMTrain/05-速查表/术语速查#term-loss" class="wiki-term" data-wiki-title="loss" data-wiki-summary="训练目标对应的误差标量，优化器尝试让它下降。" data-wiki-misconception="一个 loss 数值足以代表模型的全部质量。">损失</a>、<a href="/LLMTrain/05-速查表/术语速查#term-learning-rate" class="wiki-term" data-wiki-title="learning rate" data-wiki-summary="控制每次参数更新幅度的超参数。" data-wiki-misconception="学习率越大，训练一定越快越好。">学习率</a>、<a href="/LLMTrain/05-速查表/术语速查#term-batch" class="wiki-term" data-wiki-title="batch" data-wiki-summary="一次前向与反向计算共同处理的一组样本。" data-wiki-misconception="一个 batch 必然等于一次优化器更新或整个数据集。">batch</a>、<a href="/LLMTrain/05-速查表/术语速查#term-epoch" class="wiki-term" data-wiki-title="epoch" data-wiki-summary="训练过程大致遍历一遍训练集。" data-wiki-misconception="一个 epoch 总有固定数量的 step。">epoch</a>、<a href="/LLMTrain/05-速查表/术语速查#term-overfitting" class="wiki-term" data-wiki-title="overfitting" data-wiki-summary="模型继续改善训练数据表现，却不能同步改善未见数据表现的现象。" data-wiki-misconception="训练 loss 下降就一定没有过拟合。">过拟合</a>等训练日志。</li><li>在 CPU 或 GPU 上训练一个小型 Decoder-only <a href="/LLMTrain/05-速查表/术语速查#term-transformer" class="wiki-term" data-wiki-title="Transformer" data-wiki-summary="由注意力、MLP、残差连接和归一化等模块组成的一类神经网络架构。" data-wiki-misconception="所有大模型都只能采用同一种 Transformer 结构。">Transformer</a>。</li><li>用验证<a href="/LLMTrain/05-速查表/术语速查#term-loss" class="wiki-term" data-wiki-title="loss" data-wiki-summary="训练目标对应的误差标量，优化器尝试让它下降。" data-wiki-misconception="一个 loss 数值足以代表模型的全部质量。">损失</a>、固定提示词和对照实验判断模型是否真的变好。</li><li>交付配置、<a href="/LLMTrain/05-速查表/术语速查#term-checkpoint" class="wiki-term" data-wiki-title="checkpoint" data-wiki-summary="训练过程保存的权重及恢复训练所需状态快照。" data-wiki-misconception="checkpoint 天然就是可直接上线的完整产品。">检查点</a>、样例、指标和模型卡，使实验能够复现。</li></ul><h2 id="仓库分区" tabindex="-1">仓库分区 <a class="header-anchor" href="#仓库分区" aria-label="Permalink to &quot;仓库分区&quot;">​</a></h2><table tabindex="0"><thead><tr><th>目录</th><th>用途</th></tr></thead><tbody><tr><td><code>00-从这里开始</code></td><td>路线、目标、打卡与环境选择</td></tr><tr><td><code>01-14天理论课</code></td><td>必修主线，按编号阅读</td></tr><tr><td><code>02-第3周实战</code></td><td>七天训练项目和可运行代码</td></tr><tr><td><code>03-数学急救包</code></td><td>只讲训练会用到的数学</td></tr><tr><td><code>04-图解与数字漫画</code></td><td>难点视觉材料</td></tr><tr><td><code>05-速查表</code></td><td>术语、公式、选型和排错</td></tr><tr><td><code>06-拓展知识库</code></td><td>主线之外的领域索引</td></tr><tr><td><code>07-来源与质量审计</code></td><td>来源、版本、勘误和审校记录</td></tr><tr><td><code>原始素材</code></td><td>原始 Obsidian 素材，只读保留</td></tr></tbody></table><blockquote><p>课程中的“理解”是指能够解释、比较、操作和验证，不等于能在 14 天内掌握全部论文推导或大规模集群工程。</p></blockquote><h2 id="网页版" tabindex="-1">网页版 <a class="header-anchor" href="#网页版" aria-label="Permalink to &quot;网页版&quot;">​</a></h2><div class="language-powershell vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">pnpm install</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">pnpm docs:dev</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>生产构建使用 <code>pnpm docs:build</code>，输出位于 <code>.vitepress/dist/</code>。课程 Markdown 仍是唯一内容源；网页学习进度仅保存在当前浏览器。</p><p>内容扩充必须遵守 <a href="./07-来源与质量审计/内容编写规范">内容编写规范</a>：核心术语统一登记，正文自动链接并提供悬停预览，不能在文章之间复制出互相冲突的定义。</p>`,13)])])}const k=t(d,[["render",s]]);export{p as __pageData,k as default};
